const chronotypeOptions: { id: Chronotype; label: string; icon: ReactNode }[] = [
  { id: 'Lion', label: 'Lion', icon: <LionIcon /> },
  { id: 'Wolf', label: 'Wolf', icon: <WolfIcon /> },
  { id: 'Bear', label: 'Bear', icon: <BearIcon /> },
  { id: 'Dolphin', label: 'Dolphin', icon: <DolphinIcon /> },
];

const chronotypeIconMap: Record<Chronotype, ReactNode> = {
  Lion: <LionIcon />,
  Wolf: <WolfIcon />,
  Bear: <BearIcon />,
  Dolphin: <DolphinIcon />,
};

function App({ section = "rhythm" }: { section?: string }) {
  const { taskLists: savedTaskLists, timeblocks: savedTimeblocks, liveTimer, save, setSavedTaskLists, setSavedTimeblocks, ready, error: storageError, reload } = useRhythmLibrary();
  const [timerOpen, setTimerOpen] = useState(false);
  const [startingTimer, setStartingTimer] = useState(false);

  const [dayConfig, setDayConfig] = useState<DayConfig>({
    date: todayStr,
    startTime: '09:00',
    endTime: '18:00',
    chronotype: 'Bear',
    timezone: DEVICE_TIME_ZONE,
  });

  const [tasks, setTasks] = useState<Task[]>([]);
  const [showFlowModal, setShowFlowModal] = useState(false);
  const flowDialog = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    if (!showFlowModal) return;
    const trigger = document.activeElement as HTMLElement | null;
    flowDialog.current?.showModal();
    const before = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = before; trigger?.focus({preventScroll:true}); };
  }, [showFlowModal]);
  const [flowStep, setFlowStep] = useState<'chronotype' | 'tasks'>('tasks');
  const [flowContext, setFlowContext] = useState<'task-list' | 'timeblock'>(
    'task-list'
  );
  const [taskBuilderInitialStep, setTaskBuilderInitialStep] = useState<
    'tasks' | 'adjust' | 'range'
  >('tasks');
  const [taskFlowTheme, setTaskFlowTheme] = useState<'light' | 'dark'>('light');
  const [taskFlowStage, setTaskFlowStage] = useState<
    'tasks' | 'adjust' | 'range-select' | 'range-blocks' | 'range-export'
  >('tasks');
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
      flowDialog.current?.querySelector('.flow-modal')?.scrollTo({ top: 0 });
    });
    return () => cancelAnimationFrame(frame);
  }, [flowStep, taskFlowStage, showFlowModal]);

  const [expandedTaskListId, setExpandedTaskListId] = useState<string | null>(
    () => savedTaskLists[0]?.id ?? 'preview-task-list-1'
  );
  const [activeTaskListId, setActiveTaskListId] = useState<string | null>(null);

  const [activeTimeblockId, setActiveTimeblockId] = useState<string | null>(null);
  const [taskListSearch, setTaskListSearch] = useState('');
  const [timeblockSearch, setTimeblockSearch] = useState('');
  const [isTimeblockEditMode, setIsTimeblockEditMode] = useState(false);
  const [draftTimeRange, setDraftTimeRange] = useState<{
    startTime: string;
    endTime: string;
  } | null>(null);

  const filteredTaskLists = useMemo(() => {
    if (!taskListSearch.trim()) return savedTaskLists;
    const query = taskListSearch.toLowerCase();
    return savedTaskLists.filter(list => list.name.toLowerCase().includes(query));
  }, [savedTaskLists, taskListSearch]);

  const filteredTimeblocks = useMemo(() => {
    if (!timeblockSearch.trim()) return savedTimeblocks;
    const query = timeblockSearch.toLowerCase();
    return savedTimeblocks.filter(block => block.name.toLowerCase().includes(query));
  }, [savedTimeblocks, timeblockSearch]);





  const handleAddTask = (task: Task) => {
    setTasks(prev => [...prev, task]);
  };

  const handleUpdateTask = (id: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(t => (t.id === id ? { ...t, ...updates } : t)));
  };

  const handleRemoveTask = (id: string) => {
    setTasks(prev => prev.filter(t => t.id !== id));
  };

  const handleReorderTasks = (nextOrder: Task[]) => {
    setTasks(nextOrder);
  };

  const handleExportTimeblocks = () => {
    if (!tasks.length) return;
    const scheduleBlocks = buildManualSchedule(tasks, dayConfig);
    if (!scheduleBlocks.length) return;
    const fileName = formatICSFileName(dayConfig.date);
    generateICS(scheduleBlocks, fileName, dayConfig.timezone);
  };

  const handleStartLiveTimer = async (exportCalendar = false) => {
    if (startingTimer) return;
    const blocks = buildManualSchedule(tasks, dayConfig);
    if (!blocks.length) return;
    setStartingTimer(true);
    const timer = {
      id: crypto.randomUUID(),
      name: savedTimeblocks.find(block => block.id === activeTimeblockId)?.name ?? "Today's Plan",
      timezone: dayConfig.timezone,
      blocks,
    };
    const saved = await save(data => ({ ...data, liveTimer: timer }));
    setStartingTimer(false);
    if (!saved) return;
    if (exportCalendar) generateICS(blocks, formatICSFileName(dayConfig.date), dayConfig.timezone);
    closeFlowModal();
    setTimerOpen(true);
  };

  const handleTimezoneChange = (timezone: string) => {
    setDayConfig(prev => ({ ...prev, timezone }));
  };

  const resetFlowVisualState = () => {
    setTaskFlowStage('tasks');
    setTaskFlowTheme('light');
    setTaskBuilderInitialStep('tasks');
  };

  const closeFlowModal = () => {
    setShowFlowModal(false);
    setFlowStep('tasks');
    setFlowContext('task-list');
    setTasks([]);
    setActiveTaskListId(null);
    setActiveTimeblockId(null);
    setDraftTimeRange(null);
    resetFlowVisualState();
  };

  const handleChronotypeSelect = (ct: Chronotype) => {
    setDayConfig(prev => ({ ...prev, chronotype: ct }));
  };

  const handleStartNewTimeblock = () => {
    resetFlowVisualState();
    setFlowContext('timeblock');
    setFlowStep('chronotype');
    setTaskBuilderInitialStep('tasks');
    setActiveTaskListId(null);
    setActiveTimeblockId(null);
    setTasks([]);
    setDraftTimeRange(null);
    setShowFlowModal(true);
  };

  const handleLoadSavedTimeblock = (timeblockId: string) => {
    const block = savedTimeblocks.find(tb => tb.id === timeblockId);
    if (!block) return;
    setFlowContext('timeblock');
    resetFlowVisualState();
    setActiveTaskListId(null);
    setActiveTimeblockId(block.id);
    setTasks(block.tasks.map(task => ({ ...task })));
    setDayConfig(prev => ({
      ...block.dayConfig,
      date: prev.date,
    }));
    setDraftTimeRange({
      startTime: block.dayConfig.startTime,
      endTime: block.dayConfig.endTime,
    });
    setTaskBuilderInitialStep('tasks');
    setFlowStep('tasks');
    setShowFlowModal(true);
  };

  const handleDeleteTimeblock = (timeblockId: string) => {
    const block = savedTimeblocks.find(item => item.id === timeblockId);
    if (!block || typeof window === 'undefined') return;
    const shouldDelete = window.confirm(`Delete "${block.name}"?`);
    if (!shouldDelete) return;
    setSavedTimeblocks(prev => prev.filter(item => item.id !== timeblockId));
    setActiveTimeblockId(current => (current === timeblockId ? null : current));
  };

  const handleStartTaskList = () => {
    resetFlowVisualState();
    setFlowContext('task-list');
    setFlowStep('tasks');
    setTaskBuilderInitialStep('tasks');
    setActiveTimeblockId(null);
    setActiveTaskListId(null);
    setTasks([]);
    setDraftTimeRange(null);
    setShowFlowModal(true);
  };

  const handleLoadSavedTaskList = (taskListId: string) => {
    const list = savedTaskLists.find(item => item.id === taskListId);
    if (!list) return;
    setFlowContext('task-list');
    resetFlowVisualState();
    setFlowStep('tasks');
    setTaskBuilderInitialStep('tasks');
    setActiveTimeblockId(null);
    setActiveTaskListId(list.id);
    setTasks(list.tasks.map(task => ({ ...task })));
    setDraftTimeRange(null);
    setShowFlowModal(true);
  };

  const handleDeleteTaskList = (taskListId: string) => {
    const list = savedTaskLists.find(item => item.id === taskListId);
    if (!list || typeof window === 'undefined') return;
    const shouldDelete = window.confirm(`Delete "${list.name}"?`);
    if (!shouldDelete) return;
    setSavedTaskLists(prev => prev.filter(item => item.id !== taskListId));
    setExpandedTaskListId(current => (current === taskListId ? null : current));
    setActiveTaskListId(current => (current === taskListId ? null : current));
  };

  const handleTimeblockSavedTaskList = (taskListId: string) => {
    const list = savedTaskLists.find(item => item.id === taskListId);
    if (!list) return;
    resetFlowVisualState();
    setFlowContext('timeblock');
    setFlowStep('chronotype');
    setTaskBuilderInitialStep('tasks');
    setActiveTaskListId(list.id);
    setActiveTimeblockId(null);
    setTasks(list.tasks.map(task => ({ ...task })));
    setDraftTimeRange(null);
    setShowFlowModal(true);
  };

  const handleSaveTaskList = async () => {
    if (!tasks.length) return;
    const existing = activeTaskListId
      ? savedTaskLists.find(list => list.id === activeTaskListId)
      : null;
    const defaultName =
      existing?.name ||
      `Task List ${new Date().toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
      })}`;
    if (typeof window === 'undefined') return;
    const nameInput = window.prompt('Name this task list', defaultName);
    if (nameInput === null) return;
    const trimmed = nameInput.trim();
    if (!trimmed) return;
    const payload: SavedTaskList = {
      id: existing?.id ?? crypto.randomUUID(),
      name: trimmed,
      createdAt: existing?.createdAt ?? new Date().toISOString(),
      tasks: tasks.map(task => ({ ...task })),
    };
    const saved = await setSavedTaskLists(prev => {
      if (existing) {
        return prev.map(list => (list.id === payload.id ? payload : list));
      }
      return [payload, ...prev];
    });
    if (saved) closeFlowModal();
  };

  const handleTimeblockTaskList = () => {
    if (!tasks.length) return;
    setFlowContext('timeblock');
    setActiveTimeblockId(null);
    setTaskFlowStage('adjust');
    setTaskFlowTheme('dark');
    setTaskBuilderInitialStep('adjust');
    setDraftTimeRange(null);
    setFlowStep('chronotype');
  };

  const handleSaveCurrentTimeblock = async () => {
    if (!tasks.length) return;
    const existing = activeTimeblockId
      ? savedTimeblocks.find(tb => tb.id === activeTimeblockId)
      : null;
    const defaultName =
      existing?.name ||
      `Timeblock ${new Date().toLocaleDateString(undefined, {
        month: 'short',
        day: 'numeric',
      })}`;
    if (typeof window === 'undefined') return;
    const nameInput = window.prompt('Name this timeblock', defaultName);
    if (nameInput === null) return;
    const trimmed = nameInput.trim();
    if (!trimmed) return;
    const payload: SavedTimeblock = {
      id: existing?.id ?? crypto.randomUUID(),
      name: trimmed,
      createdAt: existing?.createdAt ?? new Date().toISOString(),
      dayConfig: { ...dayConfig },
      tasks: tasks.map(task => ({ ...task })),
    };
    const saved = await setSavedTimeblocks(prev => {
      if (existing) {
        return prev.map(block => (block.id === payload.id ? payload : block));
      }
      return [payload, ...prev];
    });
    if (saved) closeFlowModal();
  };

  const modalThemeClass =
    flowStep === 'chronotype'
      ? 'modal-chronotype'
      : taskFlowTheme === 'dark'
      ? 'modal-task'
      : 'modal-chronotype';
  const modalSize =
    flowStep === 'chronotype'
      ? 'compact'
      : taskFlowStage === 'tasks'
      ? 'roomy'
      : taskFlowStage === 'adjust'
      ? 'expanded'
      : taskFlowStage === 'range-select'
      ? 'tall'
      : taskFlowStage === 'range-blocks'
      ? 'xl'
      : taskFlowStage === 'range-export'
      ? 'calendar'
      : 'roomy';

  if (!ready) return <div className="platform-notice" role="status">{storageError || 'Loading your planning space…'}{storageError && <button onClick={reload}>Try again</button>}</div>;
  return (
    <div className="app">
      {storageError && <div className="platform-notice" role="alert">{storageError}</div>}
      <div className="app-main">
        {section === 'rhythm-timeblocks' && liveTimer && <LiveTimerPreview timer={liveTimer} onOpen={() => setTimerOpen(true)} />}
        <section className={`dashboard-shell${section === "rhythm-tasks" || section === "rhythm-timeblocks" ? " single-panel" : ""}`} aria-label="Rhythm dashboard">
          {section !== "rhythm-timeblocks" && <div className="task-panel" id="rhythm-task-lists">
            <div className="dashboard-header task-panel-header">
              <div>
                <p className="section-kicker">Task List</p>
                <h1>Saved task-lists appear in this section</h1>
              </div>
              <label className="dashboard-search">
                  <span className="sr-only">Search task lists</span>
                  <input
                    type="search"
                    placeholder="Search Task Lists"
                    value={taskListSearch}
                    onChange={e => setTaskListSearch(e.target.value)}
                  />
              </label>
            </div>

            <button type="button" className="add-list-card" onClick={handleStartTaskList}>
              <ListIcon />
              <span>Add Task List</span>
            </button>

            <div className="task-list-stack">
              {filteredTaskLists.map(list => {
                const isExpanded = expandedTaskListId === list.id;
                return (
                  <article
                    key={list.id}
                    className={`task-list-card${isExpanded ? ' expanded' : ''}`}
                    onClick={() => {
                      handleLoadSavedTaskList(list.id);
                    }}
                  >
                    <div className="task-card-topline">
                      <div className="task-card-identity">
                        <ListIcon />
                        <div>
                          <p className="card-eyebrow">Task List</p>
                          <h2>{list.name}</h2>
                          <p>Created on {new Date(list.createdAt).toLocaleDateString()}</p>
                        </div>
                        <div className="meta-row">
                          <MetaChip icon={<FileIcon />} label={`${list.tasks.length} tasks`} />
                          <MetaChip
                            icon={<ClockIcon />}
                            label={formatMinutesFromTasks(list.tasks)}
                          />
                        </div>
                      </div>
                      <div className="task-card-actions">
                        <button
                          type="button"
                          className="glass-action"
                          onClick={event => {
                            event.stopPropagation();
                            handleLoadSavedTaskList(list.id);
                          }}
                        >
                          <span>Edit</span>
                          <EditIcon />
                        </button>
                        <button
                          type="button"
                          className="glass-action danger"
                          onClick={event => {
                            event.stopPropagation();
                            handleDeleteTaskList(list.id);
                          }}
                        >
                          <span>Delete</span>
                          <TrashIcon />
                        </button>
                        <button
                          type="button"
                          className="glass-action emphasis"
                          onClick={event => {
                            event.stopPropagation();
                            handleTimeblockSavedTaskList(list.id);
                          }}
                        >
                          <span>Timeblock</span>
                          <GridIcon />
                        </button>
                        <button
                          type="button"
                          className="chevron-button"
                          aria-label={isExpanded ? 'Collapse task list' : 'Expand task list'}
                          aria-expanded={isExpanded}
                          onClick={event => {
                            event.stopPropagation();
                            setExpandedTaskListId(current =>
                              current === list.id ? null : list.id
                            );
                          }}
                        >
                          <ChevronIcon flipped={isExpanded} />
                        </button>
                      </div>
                    </div>

                    {isExpanded && (
                      <div className="task-card-details">
                        <p className="card-eyebrow">Tasks</p>
                        <div className="task-rows">
                          {list.tasks.slice(0, 5).map((task, taskIndex) => (
                            <div className="task-row" key={task.id}>
                              <div>
                                <p className="card-eyebrow">Task {taskIndex + 1}</p>
                                <h3>{task.name}</h3>
                              </div>
                              <div className="meta-row">
                                <MetaChip icon={<BoltIcon />} label={String(task.energyRequired)} />
                                <MetaChip
                                  icon={<ClockIcon />}
                                  label={formatMinutesValue(task.durationMinutes)}
                                />
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </article>
                );
              })}
              {!filteredTaskLists.length && (
                <p className="dashboard-empty">
                  {taskListSearch.trim()
                    ? 'No matching task lists.'
                    : 'No saved task lists yet.'}
                </p>
              )}
            </div>
          </div>}

          {section !== "rhythm-tasks" && <aside className="timeblocks-panel" id="rhythm-timeblocks">
            <div className="dashboard-header">
              <div className="timeblocks-title-row">
                <div>
                  <p className="section-kicker">Timeblocks</p>
                  <h1>Saved and in-progress timeblocking plans appear here</h1>
                </div>
                <button
                  type="button"
                  className={`timeblock-edit-toggle${isTimeblockEditMode ? ' active' : ''}`}
                  aria-pressed={isTimeblockEditMode}
                  onClick={() => setIsTimeblockEditMode(current => !current)}
                >
                  <span>{isTimeblockEditMode ? 'Done' : 'Edit'}</span>
                  <EditIcon />
                </button>
              </div>
              <label className="dashboard-search compact">
                <span className="sr-only">Search timeblocks</span>
                <input
                  type="search"
                  placeholder="Search Timeblocks"
                  value={timeblockSearch}
                  onChange={e => setTimeblockSearch(e.target.value)}
                />
              </label>
            </div>

            <button type="button" className="add-timeblock-card" onClick={handleStartNewTimeblock}>
              <GridIcon />
              <span>Add Timeblock</span>
            </button>

            <div className="timeblock-stack">
              {filteredTimeblocks.map(block => {
                return (
                  <article
                    key={block.id}
                    className={`timeblock-rail-card${isTimeblockEditMode ? ' editing' : ''}`}
                    onClick={() => {
                      handleLoadSavedTimeblock(block.id);
                    }}
                  >
                    <span className="chronotype-mark" aria-hidden="true">
                      {chronotypeIconMap[block.dayConfig.chronotype]}
                    </span>
                    <div className="timeblock-copy">
                      <p className="card-eyebrow">{block.dayConfig.chronotype}</p>
                      <h2>{block.name}</h2>
                      <p>{formatTimeWindow(block.dayConfig.startTime, block.dayConfig.endTime)}</p>
                    </div>
                    <div className="timeblock-control-group">
                      <div className="timeblock-metrics">
                        <MetaChip icon={<FileIcon />} label={`${block.tasks.length} tasks`} />
                        <MetaChip
                          icon={<ClockIcon />}
                          label={formatMinutesFromTasks(block.tasks)}
                        />
                      </div>
                      <button
                        type="button"
                        className="timeblock-delete-button"
                        aria-label={`Delete ${block.name}`}
                        tabIndex={isTimeblockEditMode ? 0 : -1}
                        onClick={event => {
                          event.stopPropagation();
                          handleDeleteTimeblock(block.id);
                        }}
                      >
                        <TrashIcon />
                      </button>
                    </div>
                  </article>
                );
              })}
              {!filteredTimeblocks.length && (
                <p className="dashboard-empty">
                  {timeblockSearch.trim()
                    ? 'No matching timeblocks.'
                    : 'No saved timeblocks yet.'}
                </p>
              )}
            </div>
          </aside>}
        </section>
      </div>
      {showFlowModal && (
        <dialog ref={flowDialog} className="flow-modal-backdrop" aria-label={flowContext === 'task-list' ? 'Build a task list' : 'Create a timeblock'} onCancel={e => { e.preventDefault(); closeFlowModal(); }}>
          <div className={`flow-modal flow-unified ${modalThemeClass}`} data-modal-size={modalSize}>
            {flowStep === 'chronotype' ? (
              <div className="task-step chronotype-step">
                <div className="task-step-header">
                  <div>
                    <p className="eyebrow">Create a Timeblock</p>
                    <h3>Choose your Rhythm</h3>
                    <p className="task-step-subhead">
                      How does your energy flow through the day?
                    </p>
                  </div>
                  <div className="task-header-actions">
                    <button className="task-step-done" onClick={closeFlowModal}>
                      Cancel
                    </button>
                    <button className="task-step-primary" onClick={() => setFlowStep('tasks')}>
                      Next
                    </button>
                  </div>
                </div>

                <div className="chronotype-options">
                  {chronotypeOptions.map(option => (
                    <button
                      type="button"
                      key={option.id}
                      className={
                        'chronotype-card' +
                        (dayConfig.chronotype === option.id ? ' selected' : '')
                      }
                      onClick={() => handleChronotypeSelect(option.id)}
                      aria-pressed={dayConfig.chronotype === option.id}
                    >
                      <span className="icon" aria-hidden="true">
                        {option.icon}
                      </span>
                      <span>{option.label}</span>
                    </button>
                  ))}
                </div>

                <ChronotypeGraph type={dayConfig.chronotype} />
              </div>
            ) : (
              <TaskBuilderStep
                key={`${flowContext}:${taskBuilderInitialStep}`}
                tasks={tasks}
                chronotype={dayConfig.chronotype}
                date={dayConfig.date}
                onAdd={handleAddTask}
                onUpdate={handleUpdateTask}
                onRemove={handleRemoveTask}
                onReorder={handleReorderTasks}
                timeZone={dayConfig.timezone}
                onTimeZoneChange={handleTimezoneChange}
                onExport={handleExportTimeblocks}
                onStartLiveTimer={handleStartLiveTimer}
                startingTimer={startingTimer}
                startTime={draftTimeRange?.startTime ?? ''}
                endTime={draftTimeRange?.endTime ?? ''}
                onRangeChange={(startTime, endTime) => {
                  setDraftTimeRange({ startTime, endTime });
                  setDayConfig(prev => ({ ...prev, startTime, endTime }));
                }}
                onDone={closeFlowModal}
                onThemeChange={setTaskFlowTheme}
                onStageChange={setTaskFlowStage}
                mode={flowContext}
                initialStep={taskBuilderInitialStep}
                onSaveTaskList={flowContext === 'task-list' ? handleSaveTaskList : undefined}
                onStartTimeblock={
                  flowContext === 'task-list' ? handleTimeblockTaskList : undefined
                }
                onSaveTimeblock={
                  flowContext === 'timeblock' ? handleSaveCurrentTimeblock : undefined
                }
              />
            )}
          </div>
        </dialog>
      )}
      {timerOpen && liveTimer && <LiveTimerModal timer={liveTimer} onClose={() => setTimerOpen(false)} />}
    </div>
  );
}

function MetaChip({ icon, label }: { icon: ReactNode; label: string }) {
  return (
    <span className="meta-chip">
      {icon}
      <span>{label}</span>
    </span>
  );
}

